import os, shutil, subprocess, sys
import glob
hits = sorted(glob.glob("/kaggle/input/**/train.csv", recursive=True))
assert hits, "train.csv not found under /kaggle/input"
PUB = os.path.dirname(hits[0])
print("data dir:", PUB)
SRCS = {'solution.py': '# eris-template-version: 3\n"""Complementary Entity Evidence Selection: anchor-conditioned role tagger + expected-union pair decode.\n\nReads <public_dir>, trains a transformer inside this script, writes <submission_out> (id, prediction).\n\nChallenge requirements map (how each explicit requirement of the description is met):\n  * hardware / runtime: one A10G, 90 min -> device fixed to cuda, fixed work plan (see constants), time is logged only.\n  * required methods: real training of a pretrained encoder (full fine-tuning) on the supplied training slates; in-script cohort CV\n    chooses the epoch count and the calibration temperature; the final model is refit on 100% of train.\n  * prohibited: no web, no annotation mirrors, no external or synthetic examples, no generated sentences or pseudo-labels, no id\n    reverse-mapping (ids are used only to group rows into slates and to align the output), no candidate-order signal, no test-set\n    statistics (test rows are only run through the frozen trained model, one slate at a time).\n  * output: id,prediction for every test id, finite floats; larger = selected earlier within its slate.\n\nDesign (why):\n  * The hidden target of a candidate is its incident role inventory minus the seed\'s known roles. So the seed only acts as a HARD MASK\n    (a known role can never be "new"); the learning problem is "which roles does this sentence assert about the anchor?".\n  * The model is a sentence-level multi-label role tagger. Labels are partially observed (a role listed in known_roles is unobserved for\n    that row), hence a masked binary cross-entropy. The same sentence can appear in several train slates with different seeds, so its\n    observed labels are merged across appearances; train seed sentences are extra examples whose label is exactly their known_roles.\n  * The metric rewards the UNION of the chosen pair relative to the best pair, so the decode picks the pair with the largest expected\n    union of new roles under the calibrated role probabilities (redundant candidates are penalised automatically).\n"""\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport re\nimport sys\nimport time\nfrom collections import defaultdict\nfrom itertools import combinations\nfrom pathlib import Path\n\nPUBLIC_DIR = Path(sys.argv[1]) if len(sys.argv) > 1 else Path("./dataset/public")\nSUBMISSION_OUT = Path(sys.argv[2]) if len(sys.argv) > 2 else Path("./working/submission.csv")\nWORK_DIR = SUBMISSION_OUT.parent\nWORK_DIR.mkdir(parents=True, exist_ok=True)\n\nos.environ["PYTHONHASHSEED"] = "0"\nos.environ["TOKENIZERS_PARALLELISM"] = "false"\nos.environ["CUBLAS_WORKSPACE_CONFIG"] = ":4096:8"\nos.environ["HF_HOME"] = str(WORK_DIR / "hf_cache")\n\nimport numpy as np\nimport pandas as pd\nimport torch\nimport torch.nn as nn\nfrom transformers import AutoModel, AutoTokenizer, get_linear_schedule_with_warmup\n\n# ---- fixed plan (constants; time is never used in a condition) -------------------------------------\nMODEL_NAME = "microsoft/deberta-v3-large"\nMODEL_REVISION = "main"         # DEV NOTE: pin to an exact commit sha before the final submission\nDEVICE = "cuda"\nAMP_DTYPE = "bfloat16"          # fixed; bf16 is native on the A10G. dev_run.py may set "float32" on pre-Ampere dev GPUs (no bf16 hardware)\nSEED = 42\nN_FOLDS = 5\nMAX_EPOCHS = 4                  # the LR schedule is defined for MAX_EPOCHS; the final refit trains the CV-chosen epoch count\nBATCH_SIZE = 16\nLR_ENCODER = 2e-5\nLR_HEAD = 1e-3\nLLRD = 0.9                      # layer-wise LR decay\nWARMUP = 0.1\nMAX_LEN = 160\nFINAL_SEEDS = 2\nT0 = time.time()                # LOGGING ONLY\n\n\ndef log(msg):\n    print(f"[{time.time() - T0:7.0f}s] {msg}", flush=True)\n\n\ndef seed_everything(seed):\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    torch.cuda.manual_seed_all(seed)\n    torch.backends.cudnn.deterministic = True\n    torch.backends.cudnn.benchmark = False\n    torch.use_deterministic_algorithms(True, warn_only=True)\n\n\n# ---- data ------------------------------------------------------------------------------------------\ndef slate_key(row_id):\n    """ids look like ev_<slate-key>_<candidate-key>; the middle key only groups rows into slates."""\n    return row_id.split("_")[1]\n\n\ndef cohort_key(anchor, anchor_type):\n    return re.sub(r"\\s+", " ", str(anchor).strip().lower()) + "|" + str(anchor_type).strip().lower()\n\n\ndef mark_anchor(text, start, end, anchor_type):\n    """Wrap the anchor mention in typed entity markers so the encoder knows which entity\'s roles to tag."""\n    if start is None or end is None or not (0 <= start < end <= len(text)):\n        return f"[ENT-{anchor_type}] " + text\n    return text[:start] + f" [ENT] {text[start:end]} [/ENT] " + text[end:]\n\n\ndef load_train():\n    tr = pd.read_csv(PUBLIC_DIR / "train.csv")\n    tg = pd.read_csv(PUBLIC_DIR / "train_targets.csv")\n    tg["target"] = tg["target"].map(json.loads)\n    tr = tr.merge(tg, on="id", how="left", validate="one_to_one")\n    assert tr["target"].notna().all(), "every training row needs a target"\n    tr["known"] = tr["known_roles"].map(json.loads)\n    tr["new"] = tr["target"].map(lambda t: t["roles"])\n    tr["slate"] = tr["id"].map(slate_key)\n    tr["cohort"] = [cohort_key(a, t) for a, t in zip(tr["anchor"], tr["anchor_type"])]\n    return tr\n\n\ndef build_examples(tr, roles):\n    """One example per distinct sentence. y[r]=1 if observed present; m[r]=1 if the label for role r is observed.\n    A candidate row says: roles in `new` are present; roles outside known U new are absent; roles in `known` are unobserved.\n    Train seed sentences (query_text) are fully observed: present = known_roles, all others absent."""\n    ridx = {r: i for i, r in enumerate(roles)}\n    R = len(roles)\n    ex = {}\n\n    def get(text, start, end, atype, cohort):\n        key = (text, start, end, atype)\n        if key not in ex:\n            ex[key] = dict(text=mark_anchor(text, start, end, atype), y=np.zeros(R, np.float32), m=np.zeros(R, np.float32),\n                           cohort=cohort, conflict=0)\n        return ex[key]\n\n    for row in tr.itertuples(index=False):\n        e = get(row.candidate_text, int(row.anchor_start), int(row.anchor_end), row.anchor_type, row.cohort)\n        known = {ridx[r] for r in row.known if r in ridx}\n        new = {ridx[r] for r in row.new if r in ridx}\n        for i in range(R):\n            if i in new:\n                if e["m"][i] and e["y"][i] == 0:\n                    e["conflict"] += 1\n                e["y"][i], e["m"][i] = 1.0, 1.0\n            elif i not in known:\n                if e["m"][i] and e["y"][i] == 1:\n                    e["conflict"] += 1\n                elif not e["m"][i]:\n                    e["y"][i], e["m"][i] = 0.0, 1.0\n        # seed sentence: fully observed inventory\n        a = str(row.anchor)\n        pos = str(row.query_text).find(a)\n        s, t = (pos, pos + len(a)) if pos >= 0 else (None, None)\n        sd = get(row.query_text, s, t, row.anchor_type, row.cohort)\n        sd["y"][:] = 0.0\n        sd["m"][:] = 1.0\n        for i in known:\n            sd["y"][i] = 1.0\n    out = list(ex.values())\n    log(f"examples: {len(out)} distinct sentences (incl. seeds); label conflicts across appearances: {sum(e[\'conflict\'] for e in out)}")\n    return out\n\n\n# ---- exact metric (re-implemented from the description) and decode ------------------------------------\ndef slate_score(sel, role_sets):\n    ids = list(role_sets)\n    opt = max(len(role_sets[a] | role_sets[b]) for a, b in combinations(ids, 2))\n    return len(role_sets[sel[0]] | role_sets[sel[1]]) / opt\n\n\ndef decode_pair(probs, known_idx, ids):\n    """Pick the pair maximising E|union of new roles| under independent role probabilities.\n    probs: array (n_cand, R); known_idx: per-candidate set of role indices to hard-mask (known roles can never be new)."""\n    p = probs.copy()\n    for i in range(len(ids)):\n        for r in known_idx[i]:\n            p[i, r] = 0.0\n    best, best_val = None, -1.0\n    for a, b in combinations(range(len(ids)), 2):\n        val = float(np.sum(1.0 - (1.0 - p[a]) * (1.0 - p[b])))\n        if val > best_val + 1e-12 or (abs(val - best_val) <= 1e-12 and (ids[a], ids[b]) < (ids[best[0]], ids[best[1]])):\n            best, best_val = (a, b), val\n    a, b = best\n    marg = p.sum(1) - 0.0\n    scores = {}\n    order = [i for i in sorted(range(len(ids)), key=lambda i: (-marg[i], ids[i])) if i not in (a, b)]\n    for rank, i in enumerate(order):\n        scores[ids[i]] = -float(rank + 1)\n    first, second = sorted((a, b), key=lambda i: (-marg[i], ids[i]))\n    scores[ids[first]] = 1001.0\n    scores[ids[second]] = 1000.0\n    return scores\n\n\n# ---- model -----------------------------------------------------------------------------------------\nclass RoleTagger(nn.Module):\n    def __init__(self, n_roles, tok):\n        super().__init__()\n        self.enc = AutoModel.from_pretrained(MODEL_NAME, revision=MODEL_REVISION)\n        self.enc.resize_token_embeddings(len(tok))\n        h = self.enc.config.hidden_size\n        self.ent_id = tok.convert_tokens_to_ids("[ENT]")\n        self.drop = nn.Dropout(0.1)\n        self.head = nn.Linear(2 * h, n_roles)\n\n    def forward(self, input_ids, attention_mask):\n        hs = self.enc(input_ids=input_ids, attention_mask=attention_mask).last_hidden_state\n        cls = hs[:, 0]\n        is_ent = (input_ids == self.ent_id)\n        pos = torch.where(is_ent.any(1), is_ent.float().argmax(1), torch.zeros(len(input_ids), dtype=torch.long, device=input_ids.device))\n        ent = hs[torch.arange(len(hs), device=hs.device), pos]\n        return self.head(self.drop(torch.cat([cls, ent], -1)))\n\n\ndef make_tok():\n    tok = AutoTokenizer.from_pretrained(MODEL_NAME, revision=MODEL_REVISION)\n    tok.add_special_tokens({"additional_special_tokens": ["[ENT]", "[/ENT]"]})\n    return tok\n\n\ndef batches(texts, tok, bs, shuffle, seed):\n    idx = list(range(len(texts)))\n    if shuffle:\n        random.Random(seed).shuffle(idx)\n    for i in range(0, len(idx), bs):\n        sel = idx[i:i + bs]\n        enc = tok([texts[j] for j in sel], padding=True, truncation=True, max_length=MAX_LEN, return_tensors="pt")\n        yield sel, enc["input_ids"].to(DEVICE), enc["attention_mask"].to(DEVICE)\n\n\ndef param_groups(model):\n    groups, n_layers = [], model.enc.config.num_hidden_layers\n    groups.append(dict(params=list(model.head.parameters()), lr=LR_HEAD))\n    groups.append(dict(params=list(model.enc.embeddings.parameters()), lr=LR_ENCODER * LLRD ** (n_layers + 1)))\n    for i, layer in enumerate(model.enc.encoder.layer):\n        groups.append(dict(params=list(layer.parameters()), lr=LR_ENCODER * LLRD ** (n_layers - i)))\n    rest = [p for n, p in model.enc.named_parameters() if not n.startswith(("embeddings", "encoder.layer"))]\n    if rest:\n        groups.append(dict(params=rest, lr=LR_ENCODER))\n    return groups\n\n\n@torch.no_grad()\ndef predict_logits(model, tok, texts):\n    model.eval()\n    out = np.zeros((len(texts), model.head.out_features), np.float32)\n    order = sorted(range(len(texts)), key=lambda i: len(texts[i]))        # length-sorted for speed; output realigned\n    for sel, ids, am in batches([texts[i] for i in order], tok, 64, False, 0):\n        with torch.autocast("cuda", dtype=torch.bfloat16, enabled=AMP_DTYPE == "bfloat16"):\n            lg = model(ids, am)\n        for k, j in enumerate(sel):\n            out[order[j]] = lg[k].float().cpu().numpy()\n    return out\n\n\ndef train_model(examples, n_roles, tok, epochs, seed, eval_hook=None):\n    """Fine-tune the tagger for `epochs` epochs of the MAX_EPOCHS schedule. eval_hook(epoch, model) is called after each epoch."""\n    seed_everything(seed)\n    model = RoleTagger(n_roles, tok).to(DEVICE)\n    texts = [e["text"] for e in examples]\n    Y = torch.tensor(np.stack([e["y"] for e in examples]))\n    M = torch.tensor(np.stack([e["m"] for e in examples]))\n    steps = MAX_EPOCHS * math.ceil(len(texts) / BATCH_SIZE)\n    opt = torch.optim.AdamW(param_groups(model), weight_decay=0.01)\n    sched = get_linear_schedule_with_warmup(opt, int(WARMUP * steps), steps)\n    for ep in range(epochs):\n        model.train()\n        tot, cnt = 0.0, 0\n        for sel, ids, am in batches(texts, tok, BATCH_SIZE, True, seed * 1000 + ep):\n            y, m = Y[sel].to(DEVICE), M[sel].to(DEVICE)\n            with torch.autocast("cuda", dtype=torch.bfloat16, enabled=AMP_DTYPE == "bfloat16"):\n                lg = model(ids, am)\n            loss = (nn.functional.binary_cross_entropy_with_logits(lg.float(), y, reduction="none") * m).sum() / m.sum().clamp(min=1)\n            loss.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n            opt.step()\n            sched.step()\n            opt.zero_grad(set_to_none=True)\n            tot += float(loss)\n            cnt += 1\n        log(f"  seed {seed} epoch {ep + 1}/{epochs} train loss {tot / max(1, cnt):.4f}")\n        if eval_hook is not None:\n            eval_hook(ep + 1, model)\n    return model\n\n\n# ---- cohort folds, CV ----------------------------------------------------------------------------------\ndef make_folds(tr):\n    """Greedy balanced assignment of whole cohorts to folds (a cohort never straddles train/validation)."""\n    n_slates = tr.groupby("cohort")["slate"].nunique().to_dict()\n    order = sorted(n_slates, key=lambda c: (-n_slates[c], hashlib.md5(c.encode()).hexdigest()))\n    load = [0] * N_FOLDS\n    fold_of = {}\n    for c in order:\n        f = min(range(N_FOLDS), key=lambda k: (load[k], k))\n        fold_of[c] = f\n        load[f] += n_slates[c]\n    log(f"cohort folds: slates per fold {load}")\n    return fold_of\n\n\ndef slate_probs(df, ex_index, P, ridx):\n    """Yield (slate_id, ids, probs[n,R], known_idx) for the rows of df using sentence-level probabilities P."""\n    for sid, g in df.groupby("slate", sort=True):\n        ids = list(g["id"])\n        rows = [ex_index[(r.candidate_text, int(r.anchor_start), int(r.anchor_end), r.anchor_type)] for r in g.itertuples(index=False)]\n        known = [{ridx[x] for x in k if x in ridx} for k in g["known"]]\n        yield sid, ids, np.stack([P[i] for i in rows]), known\n\n\ndef cv_scores(tr, ridx, ex_index, P_by_epoch, fold_of, gold):\n    """Mean Marginal Role Coverage@2 per epoch over all train slates, from out-of-fold probabilities."""\n    res = {}\n    for ep, P in P_by_epoch.items():\n        scores = []\n        for sid, ids, probs, known in slate_probs(tr, ex_index, P, ridx):\n            sc = decode_pair(probs, known, ids)\n            sel = sorted(ids, key=lambda i: (-sc[i], i))[:2]\n            scores.append(slate_score(sel, {i: gold[i] for i in ids}))\n        res[ep] = float(np.mean(scores))\n    return res\n\n\ndef prepare(tr):\n    """Role vocabulary (TRAIN only), distinct-sentence examples and the candidate-row -> example index."""\n    roles = sorted({r for k in tr["known"] for r in k} | {r for n in tr["new"] for r in n})\n    ridx = {r: i for i, r in enumerate(roles)}\n    examples = build_examples(tr, roles)\n    text_to_idx = {e["text"]: i for i, e in enumerate(examples)}\n    ex_index = {}\n    for r in tr.itertuples(index=False):\n        k = (r.candidate_text, int(r.anchor_start), int(r.anchor_end), r.anchor_type)\n        ex_index[k] = text_to_idx[mark_anchor(*k)]\n    return roles, ridx, examples, ex_index\n\n\ndef fit_temperature(L, Y, M):\n    """One scalar temperature fitted on out-of-fold logits by masked BCE (train-only evidence, 1 free constant)."""\n    best_T, best_nll = 1.0, 1e18\n    for T in (0.6, 0.8, 1.0, 1.25, 1.5, 2.0, 2.5):\n        p = 1.0 / (1.0 + np.exp(-L / T))\n        nll = float(-(M * (Y * np.log(p + 1e-9) + (1 - Y) * np.log(1 - p + 1e-9))).sum() / M.sum())\n        if nll < best_nll:\n            best_T, best_nll = T, nll\n    return best_T\n\n\ndef cross_validate(tr, roles, ridx, examples, ex_index, tok):\n    """Cohort-grouped K-fold. Returns OOF logits per epoch, the exact metric per epoch, the temperature per epoch."""\n    fold_of = make_folds(tr)\n    L_by_epoch = {ep: np.zeros((len(examples), len(roles)), np.float32) for ep in range(1, MAX_EPOCHS + 1)}\n    covered = np.zeros(len(examples), bool)\n    for f in range(N_FOLDS):\n        tr_ex = [e for e in examples if fold_of[e["cohort"]] != f]\n        va_idx = [i for i, e in enumerate(examples) if fold_of[e["cohort"]] == f]\n        va_texts = [examples[i]["text"] for i in va_idx]\n        log(f"fold {f}: train sentences {len(tr_ex)}, validation sentences {len(va_idx)}")\n\n        def hook(ep, model, va_idx=va_idx, va_texts=va_texts):\n            L_by_epoch[ep][va_idx] = predict_logits(model, tok, va_texts)\n\n        train_model(tr_ex, len(roles), tok, MAX_EPOCHS, SEED + f, eval_hook=hook)\n        covered[va_idx] = True\n        torch.cuda.empty_cache()\n    assert covered.all()\n    Yall = np.stack([e["y"] for e in examples])\n    Mall = np.stack([e["m"] for e in examples])\n    gold = {r.id: set(r.new) for r in tr.itertuples(index=False)}\n    temps = {ep: fit_temperature(L, Yall, Mall) for ep, L in L_by_epoch.items()}\n    probs = {ep: 1.0 / (1.0 + np.exp(-L / temps[ep])) for ep, L in L_by_epoch.items()}\n    cv = cv_scores(tr, ridx, ex_index, probs, fold_of, gold)\n    for ep in sorted(cv):\n        log(f"CV epoch {ep}: Marginal Role Coverage@2 = {cv[ep]:.4f} (temperature {temps[ep]})")\n    return L_by_epoch, cv, temps\n\n\ndef main():\n    seed_everything(SEED)\n    tr = load_train()\n    te = pd.read_csv(PUBLIC_DIR / "test.csv")\n    sample = pd.read_csv(PUBLIC_DIR / "sample_submission.csv", keep_default_na=False)\n    te["known"] = te["known_roles"].map(json.loads)\n    te["slate"] = te["id"].map(slate_key)\n    log(f"train {tr.shape} test {te.shape}")\n    tok = make_tok()\n    roles, ridx, examples, ex_index = prepare(tr)\n    log(f"{len(roles)} roles")\n\n    # 1) cohort CV: out-of-fold logits per epoch -> exact metric -> epoch count and temperature\n    _, cv, temps = cross_validate(tr, roles, ridx, examples, ex_index, tok)\n    best_ep = max(cv, key=lambda e: (cv[e], -e))\n    T_final = temps[best_ep]\n    log(f"chosen epochs for the final refit: {best_ep}; temperature {T_final}; OOF score {cv[best_ep]:.4f}")\n\n    # 2) final refit on 100% of train (FINAL_SEEDS seeds); each test slate is decoded on its own\n    te_keys = {}\n    for r in te.itertuples(index=False):\n        te_keys.setdefault((r.candidate_text, int(r.anchor_start), int(r.anchor_end), r.anchor_type), None)\n    te_texts = [mark_anchor(*k) for k in te_keys]\n    te_index = {k: i for i, k in enumerate(te_keys)}\n    logits = np.zeros((len(te_texts), len(roles)), np.float32)\n    for s in range(FINAL_SEEDS):\n        model = train_model(examples, len(roles), tok, best_ep, SEED + 100 + s)\n        logits += predict_logits(model, tok, te_texts) / FINAL_SEEDS\n        del model\n        torch.cuda.empty_cache()\n    probs = 1.0 / (1.0 + np.exp(-logits / T_final))\n    pred = {}\n    for sid, g in te.groupby("slate", sort=True):\n        ids = list(g["id"])\n        rows = [te_index[(r.candidate_text, int(r.anchor_start), int(r.anchor_end), r.anchor_type)] for r in g.itertuples(index=False)]\n        known = [{ridx[x] for x in k if x in ridx} for k in g["known"]]\n        pred.update(decode_pair(np.stack([probs[i] for i in rows]), known, ids))\n\n    sub = pd.DataFrame({"id": sample["id"], "prediction": [pred[i] for i in sample["id"]]})\n    assert list(sub.columns) == list(sample.columns) and len(sub) == len(sample) == len(te)\n    assert sub["id"].is_unique and np.isfinite(sub["prediction"].to_numpy(float)).all()\n    tmp = SUBMISSION_OUT.with_suffix(".tmp")\n    sub.to_csv(tmp, index=False)\n    os.replace(tmp, SUBMISSION_OUT)\n    log(f"wrote {SUBMISSION_OUT} shape={sub.shape}")\n\n\nif __name__ == "__main__":\n    main()\n', 'dev_run.py': '"""Dev harness (NOT part of the submission): run the cohort CV of solution.py with patched constants and save OOF logits.\nUsage: python3 dev_run.py EXP_NAME KEY=VALUE ...   e.g. MODEL_NAME=google/electra-small-discriminator DEVICE=cpu N_FOLDS=3 MAX_EPOCHS=4 BATCH_SIZE=32\nSaves reports/oof/<exp>.npz (OOF logits per epoch + labels + temperature) and prints the exact-metric CV per epoch."""\nimport importlib.util, json, sys, time\nfrom pathlib import Path\nimport numpy as np\n\nHERE = Path(__file__).resolve().parent\nargs = sys.argv[1:]\nexp, overrides = args[0], dict(a.split("=", 1) for a in args[1:])\nsys.argv = [str(HERE / "solution.py"), str(HERE / "dataset" / "public"), str(HERE / "working" / "dev_submission.csv")]\nspec = importlib.util.spec_from_file_location("solution_mod", HERE / "solution.py")\nmod = importlib.util.module_from_spec(spec)\nspec.loader.exec_module(mod)\nfor k, v in overrides.items():\n    cur = getattr(mod, k)\n    setattr(mod, k, type(cur)(v) if not isinstance(cur, str) else v)\nmod.seed_everything(mod.SEED)\ntr = mod.load_train()\ntok = mod.make_tok()\nroles, ridx, examples, ex_index = mod.prepare(tr)\nt = time.time()\nL, cv, temps = mod.cross_validate(tr, roles, ridx, examples, ex_index, tok)\nout = HERE / "reports" / "oof"\nout.mkdir(parents=True, exist_ok=True)\nnp.savez(out / f"{exp}.npz", **{f"L{ep}": v for ep, v in L.items()}, Y=np.stack([e["y"] for e in examples]), M=np.stack([e["m"] for e in examples]))\nprint(json.dumps(dict(exp=exp, overrides=overrides, cv=cv, temps=temps, wall_s=round(time.time() - t))))\n', 'metric.py': '"""Marginal Role Coverage@2 metric and metric-aware decode for complementary_entity_evidence.\n\nPure standard library (no numpy / pandas), so it can be pasted into solution.py unchanged.\n\nPart A  - exact re-implementation of the description\'s grade():\n    slate_score, marginal_role_coverage, grade_rows\nPart B  - metric-aware decode (training-free, uses only model probabilities for ONE slate at a time):\n    pair_tables_mc / choose_pair_mc_ratio       Monte-Carlo expected-ratio decode (fixed seed)\n    choose_pair_expected_union                  closed-form expected-union decode\n    pair_to_scores / decode_slate / decode_all  convert the chosen pair into within-slate ranking scores\nPart C  - toy slate generator used by the tests and the decode comparison.\n\nCompliance note: the decode operates on one slate at a time from that slate\'s own model outputs (per-sample\ninference style); it never aggregates across test slates and never branches on wall-clock time.\n"""\nimport json\nimport math\nimport random\nfrom itertools import combinations\nfrom typing import Dict, Iterable, List, Mapping, Optional, Sequence, Tuple\n\n# --------------------------------------------------------------------------------------\n# Part A: exact metric\n# --------------------------------------------------------------------------------------\n\n\ndef _numeric(value) -> float:\n    """Same coercion as the grader\'s _numeric (oracle JSON payloads map to their oracle_rank)."""\n    if isinstance(value, str) and value.lstrip().startswith("{"):\n        value = json.loads(value)["oracle_rank"]\n    try:\n        value = float(value)\n    except (TypeError, ValueError) as exc:\n        raise Exception("Predictions must be finite real ranking scores.") from exc\n    if not math.isfinite(value):\n        raise Exception("Predictions must be finite real ranking scores.")\n    return value\n\n\ndef best_pair_union(role_sets: Mapping[str, Iterable[str]]) -> int:\n    """Largest union attainable by any pair in the slate (the denominator). Needs >= 2 candidates."""\n    sets = {k: set(v) for k, v in role_sets.items()}\n    ids = list(sets)\n    if len(ids) < 2:\n        raise Exception("A slate needs at least two candidates.")\n    return max(len(sets[a] | sets[b]) for a, b in combinations(ids, 2))\n\n\ndef select_top2(scores: Mapping[str, float]) -> List[str]:\n    """Two highest scores; score ties broken by ascending candidate id (string order), as in grade()."""\n    return sorted(scores, key=lambda rid: (-scores[rid], rid))[:2]\n\n\ndef slate_score(selected_ids_or_scores, role_sets: Mapping[str, Iterable[str]]) -> float:\n    """Slate score = |union(selected pair)| / max_pair |union|.\n\n    selected_ids_or_scores is either\n      * a mapping id -> score (pair chosen exactly like grade(): -score, then ascending id), or\n      * a sequence of exactly two candidate ids (the selected pair).\n    role_sets maps every candidate id of the slate to its hidden new-role set.\n    Raises if the slate optimum is 0 (grade() raises "Scored slate has no new supported roles.").\n    """\n    sets = {k: set(v) for k, v in role_sets.items()}\n    optimum = best_pair_union(sets)\n    if optimum == 0:\n        raise Exception("Scored slate has no new supported roles.")\n    if isinstance(selected_ids_or_scores, Mapping):\n        if set(selected_ids_or_scores) != set(sets):\n            raise Exception("Scores must cover exactly the slate candidates.")\n        selected = select_top2({k: _numeric(v) for k, v in selected_ids_or_scores.items()})\n    else:\n        selected = list(selected_ids_or_scores)\n        if len(selected) != 2 or selected[0] == selected[1] or any(s not in sets for s in selected):\n            raise Exception("Selected pair must be two distinct candidates of the slate.")\n    return len(sets[selected[0]] | sets[selected[1]]) / optimum\n\n\ndef parse_gold_rows(rows: Iterable[Tuple[str, str]]) -> Dict[str, dict]:\n    """rows = (id, target_json_string). Mirrors the grader\'s _answers() payload validation."""\n    result: Dict[str, dict] = {}\n    for rid, payload in rows:\n        item = json.loads(payload)\n        if set(item) != {"query_id", "roles", "slate_size", "oracle_rank"} or not isinstance(item["query_id"], str):\n            raise Exception("Invalid answer payload.")\n        roles = item["roles"]\n        if not isinstance(roles, list) or any(not isinstance(r, str) or not r for r in roles) or len(roles) != len(set(roles)):\n            raise Exception("Invalid answer role set.")\n        if str(rid) in result:\n            raise Exception("Answers must be non-empty with unique non-missing IDs.")\n        result[str(rid)] = item\n    if not result:\n        raise Exception("Answers must be non-empty with unique non-missing IDs.")\n    return result\n\n\ndef marginal_role_coverage(predictions: Mapping[str, float], gold: Mapping[str, dict],\n                           return_per_slate: bool = False):\n    """Marginal Role Coverage@2, identical to grade(): mean over slates (grouped by query_id) of slate scores.\n\n    predictions: id -> finite score (larger = earlier).  gold: id -> {query_id, roles, slate_size, ...}.\n    Validation copied from grade(): IDs must match exactly, every slate complete (len == slate_size, all members\n    agree on slate_size, int in [2, 8]), optimum must be > 0.  Slate order of averaging is irrelevant (plain mean).\n    """\n    if not predictions:\n        raise Exception("Submission must be non-empty without missing values.")\n    if len(predictions) != len(gold) or set(map(str, predictions)) != set(gold):\n        raise Exception("Submission IDs must match scored answer IDs exactly.")\n    preds = {str(k): _numeric(v) for k, v in predictions.items()}\n    queries: Dict[str, List[str]] = {}\n    for rid, item in gold.items():\n        queries.setdefault(item["query_id"], []).append(rid)\n    scores = []\n    for members in queries.values():\n        expected = {gold[rid]["slate_size"] for rid in members}\n        if (len(expected) != 1 or any(type(n) is not int or n < 2 or n > 8 for n in expected)\n                or len(members) != next(iter(expected))):\n            raise Exception("A scoring partition must retain complete candidate slates.")\n        role_sets = {rid: set(gold[rid]["roles"]) for rid in members}\n        scores.append(slate_score({rid: preds[rid] for rid in members}, role_sets))\n    score = sum(scores) / len(scores)\n    if not 0 <= score <= 1:\n        raise Exception("Score outside [0,1].")\n    return (score, scores) if return_per_slate else score\n\n\ndef grade_rows(submission_rows: Sequence[Tuple[str, object]], answer_rows: Sequence[Tuple[str, str]]) -> float:\n    """List-of-tuples front end: submission_rows=(id, prediction), answer_rows=(id, target_json)."""\n    ids = [str(r[0]) for r in submission_rows]\n    if len(ids) != len(set(ids)):\n        raise Exception("Duplicate submission IDs.")\n    gold = parse_gold_rows(answer_rows)\n    return marginal_role_coverage({str(i): p for i, p in submission_rows}, gold)\n\n\n# --------------------------------------------------------------------------------------\n# Part B: decode\n# --------------------------------------------------------------------------------------\n# Model: candidate c holds role r independently with probability p[c][r] (known seed roles already masked to 0).\n# Closed form: E|A u B| = sum_r 1 - (1-pA_r)(1-pB_r).\n# MC expected ratio: E[ |A u B| / max_pair |.| | optimum > 0 ].  Conditioning on optimum>0 divides every pair\'s\n# value by the same constant P(opt>0), so it never changes the argmax; it only matters for the reported value.\n# Closed-form == argmax of ratio-of-expectations E|A u B| / E[opt]  (same denominator for all pairs).\n# The two differ because 1/opt varies by draw: the MC decode prefers pairs that are good in worlds where the\n# slate optimum is small (ratio is then sensitive), i.e. it hedges toward reliable coverage.\n\nPAIR_TOL = 1e-12\n\n\ndef mask_known_roles(role_probs: Mapping[str, Mapping[str, float]], known_roles: Iterable[str]) -> Dict[str, Dict[str, float]]:\n    """Hard-mask the seed\'s known roles to probability zero (they are never \'new\' by construction)."""\n    known = set(known_roles)\n    return {cid: {r: (0.0 if r in known else float(p)) for r, p in d.items()} for cid, d in role_probs.items()}\n\n\ndef _clean_probs(role_probs: Mapping[str, Mapping[str, float]]) -> Dict[str, Dict[str, float]]:\n    out = {}\n    for cid, d in role_probs.items():\n        row = {}\n        for r, p in d.items():\n            p = float(p)\n            if not math.isfinite(p) or p < 0.0 or p > 1.0:\n                raise ValueError(f"probability out of [0,1] for {cid}/{r}: {p}")\n            if p > 0.0:\n                row[r] = p\n        out[str(cid)] = row\n    if len(out) < 2:\n        raise ValueError("A slate needs at least two candidates.")\n    return out\n\n\ndef expected_union_table(role_probs: Mapping[str, Mapping[str, float]]) -> Dict[Tuple[str, str], float]:\n    """Closed-form E|union| for every pair (keys are id pairs in ascending id order)."""\n    probs = _clean_probs(role_probs)\n    ids = sorted(probs)\n    table = {}\n    for a, b in combinations(ids, 2):\n        pa, pb = probs[a], probs[b]\n        total = 0.0\n        for r in set(pa) | set(pb):\n            total += 1.0 - (1.0 - pa.get(r, 0.0)) * (1.0 - pb.get(r, 0.0))\n        table[(a, b)] = total\n    return table\n\n\ndef _argmax_pair(table: Mapping[Tuple[str, str], float]) -> Tuple[str, str]:\n    """Pair with the largest value; near-ties (<= PAIR_TOL) go to the lexicographically smallest id pair."""\n    best_pair, best_val = None, -math.inf\n    for pair in sorted(table):\n        if table[pair] > best_val + PAIR_TOL:\n            best_pair, best_val = pair, table[pair]\n    return best_pair\n\n\ndef choose_pair_expected_union(role_probs: Mapping[str, Mapping[str, float]]) -> Tuple[Tuple[str, str], Dict]:\n    """Closed-form decode: argmax_pair E|union|."""\n    table = expected_union_table(role_probs)\n    return _argmax_pair(table), table\n\n\ndef pair_tables_mc(role_probs: Mapping[str, Mapping[str, float]], n_draws: int = 2000,\n                   seed: int = 20240601) -> Tuple[Dict[Tuple[str, str], float], float]:\n    """Monte-Carlo E[ratio | opt>0] for every pair, with common random numbers across pairs.\n\n    Returns (table, p_opt_positive). Deterministic: a fresh random.Random(seed) per call and candidates processed\n    in ascending id order, so the result does not depend on dict order or on which other slates are decoded.\n    If all probabilities are 0/1 (e.g. gold oracle) a single draw is exact.\n    """\n    probs = _clean_probs(role_probs)\n    ids = sorted(probs)\n    roles = sorted({r for d in probs.values() for r in d})\n    bit = {r: 1 << i for i, r in enumerate(roles)}\n    fixed = []       # mask of roles with p == 1\n    uncertain = []   # (bit, p) for 0 < p < 1\n    for cid in ids:\n        m = 0\n        unc = []\n        for r, p in probs[cid].items():\n            if p >= 1.0:\n                m |= bit[r]\n            else:\n                unc.append((bit[r], p))\n        fixed.append(m)\n        uncertain.append(unc)\n    deterministic = not any(uncertain)\n    draws = 1 if deterministic else int(n_draws)\n    rng = random.Random(seed)\n    rnd = rng.random\n    idx_pairs = list(combinations(range(len(ids)), 2))\n    sums = [0.0] * len(idx_pairs)\n    n_pos = 0\n    n = len(ids)\n    for _ in range(draws):\n        masks = list(fixed)\n        for i in range(n):\n            m = masks[i]\n            for b, p in uncertain[i]:\n                if rnd() < p:\n                    m |= b\n            masks[i] = m\n        unions = [(masks[i] | masks[j]).bit_count() for i, j in idx_pairs]\n        opt = max(unions)\n        if opt == 0:\n            continue\n        n_pos += 1\n        inv = 1.0 / opt\n        for k, u in enumerate(unions):\n            sums[k] += u * inv\n    if n_pos == 0:\n        return {(ids[i], ids[j]): 0.0 for i, j in idx_pairs}, 0.0\n    table = {(ids[i], ids[j]): sums[k] / n_pos for k, (i, j) in enumerate(idx_pairs)}\n    return table, n_pos / draws\n\n\ndef choose_pair_mc_ratio(role_probs: Mapping[str, Mapping[str, float]], n_draws: int = 2000,\n                         seed: int = 20240601) -> Tuple[Tuple[str, str], Dict]:\n    """MC expected-ratio decode. Falls back to the closed form when every draw has optimum 0 (all-zero probs)."""\n    table, p_pos = pair_tables_mc(role_probs, n_draws, seed)\n    if p_pos == 0.0:\n        return choose_pair_expected_union(role_probs)\n    return _argmax_pair(table), table\n\n\ndef pair_to_scores(role_probs: Mapping[str, Mapping[str, float]], pair: Tuple[str, str]) -> Dict[str, float]:\n    """Within-slate scores: chosen pair on top (member with larger own expected new-role count first, ties by id),\n    remaining candidates ordered by marginal expected new roles given the pair (sum_r p_c,r * prod_{s in pair}(1-p_s,r)),\n    ties by ascending id.  Scores are distinct integers n, n-1, ..., 1, so the grader\'s tie rule is never exercised.\n    """\n    probs = _clean_probs(role_probs)\n    ids = sorted(probs)\n    a, b = pair\n    own = {c: sum(probs[c].values()) for c in ids}\n    first, second = sorted(pair, key=lambda c: (-own[c], c))\n    rest = [c for c in ids if c not in pair]\n\n    def marginal(c):\n        total = 0.0\n        for r, p in probs[c].items():\n            miss = 1.0\n            for s in (a, b):\n                miss *= 1.0 - probs[s].get(r, 0.0)\n            total += p * miss\n        return total\n\n    rest.sort(key=lambda c: (-marginal(c), c))\n    order = [first, second] + rest\n    n = len(order)\n    return {c: float(n - i) for i, c in enumerate(order)}\n\n\ndef decode_slate(role_probs: Mapping[str, Mapping[str, float]], known_roles: Optional[Iterable[str]] = None,\n                 method: str = "mc_ratio", n_draws: int = 2000, seed: int = 20240601) -> Dict[str, float]:\n    """role_probs (one slate) -> id -> ranking score.  method in {\'mc_ratio\', \'expected_union\'}."""\n    if known_roles is not None:\n        role_probs = mask_known_roles(role_probs, known_roles)\n    if method == "mc_ratio":\n        pair, _ = choose_pair_mc_ratio(role_probs, n_draws, seed)\n    elif method == "expected_union":\n        pair, _ = choose_pair_expected_union(role_probs)\n    else:\n        raise ValueError(method)\n    return pair_to_scores(role_probs, pair)\n\n\ndef decode_all(role_probs: Mapping[str, Mapping[str, float]], slate_of: Mapping[str, str],\n               known_by_slate: Optional[Mapping[str, Iterable[str]]] = None, method: str = "mc_ratio",\n               n_draws: int = 2000, seed: int = 20240601) -> Dict[str, float]:\n    """Decode every slate independently (grouping by slate key only) and merge the scores."""\n    groups: Dict[str, Dict[str, Mapping[str, float]]] = {}\n    for cid, d in role_probs.items():\n        groups.setdefault(slate_of[cid], {})[cid] = d\n    out: Dict[str, float] = {}\n    for sk, members in groups.items():\n        known = None if known_by_slate is None else known_by_slate.get(sk)\n        out.update(decode_slate(members, known, method, n_draws, seed))\n    return out\n\n\n# --------------------------------------------------------------------------------------\n# Part C: toy slates (tests / decode comparison only)\n# --------------------------------------------------------------------------------------\n\n\ndef make_toy_slate(rng: random.Random, n_roles: int = 12, informative: float = 1.0, slate_key: str = "s0"):\n    """One synthetic slate with calibrated uncertainty.\n\n    Latent per-(candidate, role) probability q ~ Beta(0.35, 2.0) scaled by a Zipf-like role prior; the gold role set is\n    Bernoulli(q); the model\'s probability is q (calibrated). informative in (0,1] shrinks q toward the role prior\n    (less informative model).  Rejection-samples until the optimum > 0 and pair utilities differ, like the real prep.\n    Returns (probs, gold_roles, ids) with probs: id -> {role: p}.\n    """\n    roles = [f"{\'in\' if i % 2 else \'out\'}:rel{i // 2}" for i in range(n_roles)]\n    prior = [min(0.9, 0.5 / (1 + i)) for i in range(n_roles)]\n    while True:\n        n = rng.randint(2, 8)\n        ids = [f"ev_{slate_key}_{rng.getrandbits(40):010x}" for _ in range(n)]\n        if len(set(ids)) != n:\n            continue\n        probs, gold = {}, {}\n        for cid in ids:\n            d, g = {}, set()\n            for i, r in enumerate(roles):\n                q = rng.betavariate(0.35, 2.0) * min(1.0, 2.5 * prior[i] * 2)\n                p = informative * q + (1 - informative) * prior[i] * 0.5\n                d[r] = p\n                if rng.random() < q:\n                    g.add(r)\n            probs[cid], gold[cid] = d, g\n        utils = {len(gold[a] | gold[b]) for a, b in combinations(ids, 2)}\n        if max(utils) > 0 and len(utils) > 1:\n            return probs, gold, ids\n'}
